// Erişim noktası (AP) modu: ESP32 kendi Wi-Fi ağını açar; modem gerekmez.
// Telefonla "KendinYap-ESP32" ağına bağlan, tarayıcıda http://192.168.4.1 adresini aç.
// Not: ledcAttach için Arduino IDE'de ESP32 kart paketi 3.x gerekir.
#include <WiFi.h>
#include <WebServer.h>

const char* AP_ADI = "KendinYap-ESP32";   // ESP32'nin açacağı ağın adı
const char* AP_PAROLA = "kendinyap123";   // en az 8 karakter; boş bırakırsan ağ şifresiz olur
const int LED1_PIN = 19;   // aç/kapat LED'i
const int LED2_PIN = 4;    // parlaklığı ayarlanan LED
const int PWM_FREKANS = 5000;
const int PWM_COZUNURLUK = 8;  // 0-255

WebServer sunucu(80);
bool led1Acik = false;
bool led2Acik = false;
int parlaklik = 128;  // LED 2 parlaklığı (0-255)

void ledleriYaz() {
  digitalWrite(LED1_PIN, led1Acik ? HIGH : LOW);
  ledcWrite(LED2_PIN, led2Acik ? parlaklik : 0);
}

String dugme(const char* yol, const char* yazi, bool acik) {
  String renk = acik ? "#16a34a" : "#64748b";
  return String("<a href='") + yol + "' style='background:" + renk + "'>" + yazi + (acik ? ": AÇIK" : ": KAPALI") + "</a>";
}

String sayfa() {
  String s = "<!doctype html><html><head><meta charset='utf-8'>";
  s += "<meta name='viewport' content='width=device-width,initial-scale=1'><title>ESP32 ışık</title>";
  s += "<style>body{font-family:sans-serif;text-align:center;padding:16px}";
  s += "a{display:block;margin:12px auto;max-width:260px;padding:14px;border-radius:10px;color:#fff;text-decoration:none;font-size:20px}";
  s += "input[type=range]{width:240px}button{padding:10px 24px;font-size:18px;border-radius:8px}</style>";
  s += "</head><body><h1>ESP32 ışık kontrolü</h1>";
  s += "<p>Ağ: " + String(AP_ADI) + " · Adres: " + WiFi.softAPIP().toString() + "</p>";
  s += dugme("/led1", "LED 1", led1Acik);
  s += dugme("/led2", "LED 2", led2Acik);
  s += "<form action='/parlaklik'><p>LED 2 parlaklığı: <b>" + String(parlaklik * 100 / 255) + " %</b></p>";
  s += "<input type='range' name='deger' min='0' max='255' value='" + String(parlaklik) + "'><br><br>";
  s += "<button type='submit'>Ayarla</button></form></body></html>";
  return s;
}

void anaSayfaya() {
  sunucu.sendHeader("Location", "/");
  sunucu.send(303);
}

void anaSayfa() { sunucu.send(200, "text/html", sayfa()); }

void led1Degistir() {
  led1Acik = !led1Acik;
  ledleriYaz();
  Serial.println(led1Acik ? "LED 1 acik" : "LED 1 kapali");
  anaSayfaya();
}

void led2Degistir() {
  led2Acik = !led2Acik;
  if (led2Acik && parlaklik == 0) parlaklik = 128;  // 0'da açılırsa hiç yanmaz
  ledleriYaz();
  Serial.println(led2Acik ? "LED 2 acik" : "LED 2 kapali");
  anaSayfaya();
}

void parlaklikAyarla() {
  if (sunucu.hasArg("deger")) {
    parlaklik = constrain(sunucu.arg("deger").toInt(), 0, 255);
    led2Acik = parlaklik > 0;
    ledleriYaz();
    Serial.printf("LED 2 parlaklik: %d\n", parlaklik);
  }
  anaSayfaya();
}

void setup() {
  Serial.begin(115200);
  pinMode(LED1_PIN, OUTPUT);
  ledcAttach(LED2_PIN, PWM_FREKANS, PWM_COZUNURLUK);
  ledleriYaz();

  WiFi.mode(WIFI_AP);
  WiFi.softAP(AP_ADI, AP_PAROLA);
  Serial.printf("Ag acildi: %s\n", AP_ADI);
  Serial.print("Tarayicida ac: http://");
  Serial.println(WiFi.softAPIP());

  sunucu.on("/", anaSayfa);
  sunucu.on("/led1", led1Degistir);
  sunucu.on("/led2", led2Degistir);
  sunucu.on("/parlaklik", parlaklikAyarla);
  sunucu.begin();
}

void loop() {
  sunucu.handleClient();
}
